import { expect } from "chai";
import { readFileSync } from "node:fs";
import { fileURLToPath } from "node:url";
import { network } from "hardhat";

const { ethers } = await network.create();

// Generated by `python -m vrag fixtures`.
const fixturePath = fileURLToPath(new URL("./fixtures/merkle.json", import.meta.url));
const fixture = JSON.parse(readFileSync(fixturePath, "utf-8")) as {
  root: string;
  name: string;
  version: string;
  passages: {
    docId: string;
    page: number;
    index: number;
    text: string;
    salt: string;
    contentHash: string;
    leaf: string;
    proof: string[];
  }[];
};

// Flip the last hex digit of a bytes32 value.
function flip(hash: string): string {
  const last = hash.slice(-1) === "0" ? "1" : "0";
  return hash.slice(0, -1) + last;
}

async function setup() {
  const [owner] = await ethers.getSigners();
  const registry = await ethers.deployContract("CorpusRegistry", [owner.address]);
  await registry.publish(fixture.root, fixture.name, fixture.version, false, fixture.passages.length);
  return registry;
}

describe("Python/Solidity Merkle fixture", () => {
  it("has enough passages to exercise odd-node promotion", () => {
    expect(fixture.passages.length).to.be.greaterThan(2);
    expect(fixture.passages.length % 2).to.equal(1);
  });

  it("recomputes every content hash from text and salt with the same encoding", () => {
    const coder = ethers.AbiCoder.defaultAbiCoder();
    for (const p of fixture.passages) {
      const expected = ethers.keccak256(coder.encode(["bytes32", "string"], [p.salt, p.text]));
      expect(p.contentHash, `${p.docId} p${p.page}:${p.index}`).to.equal(expected);
    }
  });

  it("leafOf matches every Python leaf", async () => {
    const registry = await setup();
    for (const p of fixture.passages) {
      expect(await registry.leafOf(p.docId, p.page, p.index, p.contentHash)).to.equal(p.leaf);
    }
  });

  it("accepts every Python proof", async () => {
    const registry = await setup();
    for (const p of fixture.passages) {
      expect(
        await registry.verifyPassage(0, p.proof, p.docId, p.page, p.index, p.contentHash),
        `${p.docId} p${p.page}:${p.index}`,
      ).to.equal(true);
    }
  });

  it("rejects a tampered content hash", async () => {
    const registry = await setup();
    for (const p of fixture.passages) {
      expect(await registry.verifyPassage(0, p.proof, p.docId, p.page, p.index, flip(p.contentHash))).to.equal(false);
    }
  });

  it("rejects tampered passage coordinates", async () => {
    const registry = await setup();
    const p = fixture.passages[0];
    expect(await registry.verifyPassage(0, p.proof, "other-doc", p.page, p.index, p.contentHash)).to.equal(false);
    expect(await registry.verifyPassage(0, p.proof, p.docId, p.page + 1, p.index, p.contentHash)).to.equal(false);
    expect(await registry.verifyPassage(0, p.proof, p.docId, p.page, p.index + 1, p.contentHash)).to.equal(false);
  });

  it("rejects tampered, truncated, and swapped proofs", async () => {
    const registry = await setup();
    for (const p of fixture.passages) {
      const args = [p.docId, p.page, p.index, p.contentHash] as const;
      if (p.proof.length > 0) {
        const altered = [flip(p.proof[0]), ...p.proof.slice(1)];
        expect(await registry.verifyPassage(0, altered, ...args)).to.equal(false);
        expect(await registry.verifyPassage(0, p.proof.slice(0, -1), ...args)).to.equal(false);
      }
    }
    const [a, b] = fixture.passages;
    expect(await registry.verifyPassage(0, b.proof, a.docId, a.page, a.index, a.contentHash)).to.equal(false);
  });

  it("rejects a wrong or unknown corpus ID", async () => {
    const registry = await setup();
    const p = fixture.passages[0];
    await registry.publish(flip(fixture.root), "other", "v1", false, 1);
    expect(await registry.verifyPassage(1, p.proof, p.docId, p.page, p.index, p.contentHash)).to.equal(false);
    expect(await registry.verifyPassage(99, p.proof, p.docId, p.page, p.index, p.contentHash)).to.equal(false);
  });
});
